/* rhu_pal_filestatus: the PAL's FileStatus, field for field; offsets and size at the 32-bit ARM
 * EABI asserted below. */
typedef struct rhu_pal_filestatus {
    int32_t Flags;
    int32_t Mode;
    uint32_t Uid;
    uint32_t Gid;
    int64_t Size;
    int64_t ATime;
    int64_t ATimeNsec;
    int64_t MTime;
    int64_t MTimeNsec;
    int64_t CTime;
    int64_t CTimeNsec;
    int64_t BirthTime;
    int64_t BirthTimeNsec;
    int64_t Dev;
    int64_t RDev;
    int64_t Ino;
    uint32_t UserFlags;
    uint32_t HardLinkCount;
} rhu_pal_filestatus;
RHU_PAL_STATIC_ASSERT(sizeof(rhu_pal_filestatus) == 120, "rhu_pal_filestatus size");
RHU_PAL_STATIC_ASSERT(offsetof(rhu_pal_filestatus, Flags) == 0, "rhu_pal_filestatus.Flags offset");
RHU_PAL_STATIC_ASSERT(offsetof(rhu_pal_filestatus, Mode) == 4, "rhu_pal_filestatus.Mode offset");
RHU_PAL_STATIC_ASSERT(offsetof(rhu_pal_filestatus, Uid) == 8, "rhu_pal_filestatus.Uid offset");
RHU_PAL_STATIC_ASSERT(offsetof(rhu_pal_filestatus, Gid) == 12, "rhu_pal_filestatus.Gid offset");
RHU_PAL_STATIC_ASSERT(offsetof(rhu_pal_filestatus, Size) == 16, "rhu_pal_filestatus.Size offset");
RHU_PAL_STATIC_ASSERT(offsetof(rhu_pal_filestatus, ATime) == 24, "rhu_pal_filestatus.ATime offset");
RHU_PAL_STATIC_ASSERT(offsetof(rhu_pal_filestatus, ATimeNsec) == 32, "rhu_pal_filestatus.ATimeNsec offset");
RHU_PAL_STATIC_ASSERT(offsetof(rhu_pal_filestatus, MTime) == 40, "rhu_pal_filestatus.MTime offset");
RHU_PAL_STATIC_ASSERT(offsetof(rhu_pal_filestatus, MTimeNsec) == 48, "rhu_pal_filestatus.MTimeNsec offset");
RHU_PAL_STATIC_ASSERT(offsetof(rhu_pal_filestatus, CTime) == 56, "rhu_pal_filestatus.CTime offset");
RHU_PAL_STATIC_ASSERT(offsetof(rhu_pal_filestatus, CTimeNsec) == 64, "rhu_pal_filestatus.CTimeNsec offset");
RHU_PAL_STATIC_ASSERT(offsetof(rhu_pal_filestatus, BirthTime) == 72, "rhu_pal_filestatus.BirthTime offset");
RHU_PAL_STATIC_ASSERT(offsetof(rhu_pal_filestatus, BirthTimeNsec) == 80, "rhu_pal_filestatus.BirthTimeNsec offset");
RHU_PAL_STATIC_ASSERT(offsetof(rhu_pal_filestatus, Dev) == 88, "rhu_pal_filestatus.Dev offset");
RHU_PAL_STATIC_ASSERT(offsetof(rhu_pal_filestatus, RDev) == 96, "rhu_pal_filestatus.RDev offset");
RHU_PAL_STATIC_ASSERT(offsetof(rhu_pal_filestatus, Ino) == 104, "rhu_pal_filestatus.Ino offset");
RHU_PAL_STATIC_ASSERT(offsetof(rhu_pal_filestatus, UserFlags) == 112, "rhu_pal_filestatus.UserFlags offset");
RHU_PAL_STATIC_ASSERT(offsetof(rhu_pal_filestatus, HardLinkCount) == 116, "rhu_pal_filestatus.HardLinkCount offset");

